import 'package:http/http.dart' as http;
import 'dart:convert';/// Comprehensive test script to diagnose FastAPI server issues\nclass ServerEndpointTester {\n  static const String baseUrl = 'http://192.168.100.5:8000';\n  \n  static Future<void> runAllTests() async {\n    print('🚀 FieldForce Server Endpoint Diagnostic Tool');\n    print('=' * 60);\n    print('Testing server at: $baseUrl');\n    print('');\n    \n    await testServerConnectivity();\n    await testRootEndpoint();\n    await testHealthEndpoint();\n    await testDebugRoutes();\n    await testProfileUpdateEndpoint();\n    await testCommonAlternativeEndpoints();\n    \n    print('');\n    print('=' * 60);\n    print('✅ Diagnostic tests completed');\n    print('');\n    print('📋 Summary:');\n    print('If all tests fail: Server is not running or not accessible');\n    print('If some tests pass: Server is running but missing specific endpoints');\n    print('Expected endpoint: PATCH /users/{user_id}');\n  }\n  \n  static Future<void> testServerConnectivity() async {\n    print('🔍 Testing basic server connectivity...');\n    try {\n      final response = await http.get(\n        Uri.parse(baseUrl),\n        headers: {'Content-Type': 'application/json'},\n      ).timeout(const Duration(seconds: 10));\n      \n      print('   Status: ${response.statusCode}');\n      if (response.statusCode == 200) {\n        print('   ✅ Server is reachable');\n        print('   Response: ${response.body}');\n      } else {\n        print('   ⚠️  Server responded with unexpected status');\n        print('   Response: ${response.body}');\n      }\n    } catch (e) {\n      print('   ❌ Cannot connect to server: $e');\n      print('   Check: Is FastAPI server running on 192.168.100.5:8000?');\n    }\n    print('');\n  }\n  \n  static Future<void> testRootEndpoint() async {\n    print('🔍 Testing root endpoint (/)...');\n    try {\n      final response = await http.get(\n        Uri.parse('$baseUrl/'),\n        headers: {'Content-Type': 'application/json'},\n      ).timeout(const Duration(seconds: 10));\n      \n      print('   Status: ${response.statusCode}');\n      if (response.statusCode == 200) {\n        print('   ✅ Root endpoint working');\n        try {\n          final data = jsonDecode(response.body);\n          print('   Server info: ${data['message'] ?? 'No message'}');\n          print('   Version: ${data['version'] ?? 'Unknown'}');\n        } catch (e) {\n          print('   Response: ${response.body}');\n        }\n      } else {\n        print('   ⚠️  Root endpoint returned: ${response.statusCode}');\n      }\n    } catch (e) {\n      print('   ❌ Root endpoint test failed: $e');\n    }\n    print('');\n  }\n  \n  static Future<void> testHealthEndpoint() async {\n    print('🔍 Testing health endpoint (/health)...');\n    try {\n      final response = await http.get(\n        Uri.parse('$baseUrl/health'),\n        headers: {'Content-Type': 'application/json'},\n      ).timeout(const Duration(seconds: 10));\n      \n      print('   Status: ${response.statusCode}');\n      if (response.statusCode == 200) {\n        print('   ✅ Health endpoint working');\n        print('   Response: ${response.body}');\n      } else {\n        print('   ⚠️  Health endpoint returned: ${response.statusCode}');\n      }\n    } catch (e) {\n      print('   ❌ Health endpoint test failed: $e');\n    }\n    print('');\n  }\n  \n  static Future<void> testDebugRoutes() async {\n    print('🔍 Testing debug routes endpoint (/debug/routes)...');\n    try {\n      final response = await http.get(\n        Uri.parse('$baseUrl/debug/routes'),\n        headers: {'Content-Type': 'application/json'},\n      ).timeout(const Duration(seconds: 10));\n      \n      print('   Status: ${response.statusCode}');\n      if (response.statusCode == 200) {\n        print('   ✅ Debug routes endpoint working');\n        try {\n          final data = jsonDecode(response.body);\n          final routes = data['routes'] as List?;\n          if (routes != null) {\n            print('   Available routes:');\n            for (final route in routes) {\n              final path = route['path'];\n              final methods = route['methods'];\n              print('     $methods $path');\n            }\n          }\n        } catch (e) {\n          print('   Response: ${response.body}');\n        }\n      } else {\n        print('   ⚠️  Debug routes endpoint returned: ${response.statusCode}');\n        print('   This endpoint might not be implemented');\n      }\n    } catch (e) {\n      print('   ❌ Debug routes test failed: $e');\n    }\n    print('');\n  }\n  \n  static Future<void> testProfileUpdateEndpoint() async {\n    print('🔍 Testing profile update endpoint (PATCH /users/{user_id})...');\n    \n    final testUserId = 'test-user-id';\n    final testData = {\n      'address': '123 Test Street, Test City',\n      'idDocumentUrl': 'https://example.com/test-id-document.jpg',\n      'role': 'Rep',\n      'verificationStatus': 'pending',\n      'profileImageUrl': 'https://example.com/test-profile.jpg',\n    };\n    \n    try {\n      final response = await http.patch(\n        Uri.parse('$baseUrl/users/$testUserId'),\n        headers: {\n          'Content-Type': 'application/json',\n          'Accept': 'application/json',\n          'Authorization': 'Bearer test-token-12345',\n        },\n        body: jsonEncode(testData),\n      ).timeout(const Duration(seconds: 30));\n      \n      print('   Status: ${response.statusCode}');\n      print('   Response: ${response.body}');\n      \n      if (response.statusCode == 200 || response.statusCode == 201) {\n        print('   ✅ Profile update endpoint is working correctly!');\n      } else if (response.statusCode == 404) {\n        print('   ❌ ENDPOINT NOT FOUND (404)');\n        print('   This is the exact error your app is experiencing');\n        print('   Solution: Add the PATCH /users/{user_id} endpoint to your server');\n      } else if (response.statusCode == 405) {\n        print('   ⚠️  Method not allowed (405)');\n        print('   The endpoint exists but doesn\\'t accept PATCH requests');\n        print('   Check if it expects POST, PUT, or another method');\n      } else if (response.statusCode == 422) {\n        print('   ⚠️  Validation error (422)');\n        print('   The endpoint exists but the request data format is wrong');\n      } else if (response.statusCode == 401) {\n        print('   ⚠️  Authentication required (401)');\n        print('   The endpoint exists but requires valid authentication');\n      } else {\n        print('   ⚠️  Unexpected response: ${response.statusCode}');\n      }\n    } catch (e) {\n      print('   ❌ Profile update test failed: $e');\n    }\n    print('');\n  }\n  \n  static Future<void> testCommonAlternativeEndpoints() async {\n    print('🔍 Testing common alternative endpoints...');\n    \n    final testUserId = 'test-user-id';\n    final alternatives = [\n      'PATCH /users/$testUserId',\n      'PUT /users/$testUserId',\n      'POST /users/$testUserId',\n      'PATCH /user/$testUserId',\n      'PUT /user/$testUserId',\n      'PATCH /api/users/$testUserId',\n      'PUT /api/users/$testUserId',\n      'PATCH /v1/users/$testUserId',\n      'PUT /v1/users/$testUserId',\n    ];\n    \n    for (final alt in alternatives) {\n      final parts = alt.split(' ');\n      final method = parts[0];\n      final path = parts[1];\n      \n      try {\n        http.Response response;\n        final uri = Uri.parse('$baseUrl$path');\n        final headers = {\n          'Content-Type': 'application/json',\n          'Authorization': 'Bearer test-token',\n        };\n        final body = jsonEncode({'test': 'data'});\n        \n        switch (method) {\n          case 'POST':\n            response = await http.post(uri, headers: headers, body: body)\n                .timeout(const Duration(seconds: 10));\n            break;\n          case 'PATCH':\n            response = await http.patch(uri, headers: headers, body: body)\n                .timeout(const Duration(seconds: 10));\n            break;\n          case 'PUT':\n          default:\n            response = await http.put(uri, headers: headers, body: body)\n                .timeout(const Duration(seconds: 10));\n            break;\n        }\n        \n        if (response.statusCode != 404) {\n          print('   ✅ Found alternative: $alt (Status: ${response.statusCode})');\n          if (response.statusCode == 200 || response.statusCode == 201) {\n            print('      This endpoint is working! Consider using this instead.');\n          }\n        }\n      } catch (e) {\n        // Ignore errors for alternative endpoint tests\n      }\n    }\n    print('   (Only showing endpoints that exist)');\n    print('');\n  }\n}\n\nvoid main() async {\n  await ServerEndpointTester.runAllTests();\n}\n